def word_frequency(text: str) -> dict[str, int]:
    import string
    words = [word.strip(string.punctuation) for word in text.split() if word]
    freq: dict[str, int] = {}
    for w in words:
        w = w.lower()
        freq[w] = freq.get(w, 0) + 1
    return freq
